def second_smallest(numbers):
    """
    Returns the second smallest number in the list.
    Raises a ValueError if there is no second smallest element.
    """
    if not numbers or len(numbers) < 2:
        raise ValueError("List must contain at least two elements.")

    first = second = float('inf')
    for num in numbers:
        if num < first:
            second = first
            first = num
        elif first < num < second:
            second = num

    if second == float('inf'):
        raise ValueError("No second smallest element found (all elements might be equal).")

    return second


